const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  // week_start: ISO YYYY-MM-DD opcional. Si null, calcula lunes pasado en SQL.
  const weekStartIso = body.week_start ? String(body.week_start).slice(0,10) : null;
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    week_start_iso: weekStartIso,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const r = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!r || !r.project_id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}
const weekStartStr = String(r.week_start).slice(0,10);
const weekEndStr = String(r.week_end).slice(0,10);
const activity = Array.isArray(r.activity) ? r.activity : [];
const visits = Array.isArray(r.visits) ? r.visits : [];
const incidents = Array.isArray(r.incidents) ? r.incidents : [];

// Resumen humano de actividad para meter en prompt
const activityByAgent = {};
for (const a of activity) {
  if (a.message_type === 'coordination') continue; // ruido
  activityByAgent[a.agent_name] = (activityByAgent[a.agent_name] || 0) + 1;
}
const activitySummary = Object.entries(activityByAgent)
  .map(([k,v]) => `${k}: ${v} acciones`).join('; ') || 'sin actividad relevante';

const visitsSummary = visits.length
  ? visits.map(v => `- ${String(v.visit_date).slice(0,10)}: ${v.acuerdos || '(sin acuerdos)'}`).join('\n')
  : '(sin visitas de obra esta semana)';

const incidentsSummary = incidents.length
  ? incidents.map(i => `- [${i.severity}] ${i.description} (${i.status}${i.cost_delta_eur ? `, +${i.cost_delta_eur}EUR` : ''}${i.time_delta_days ? `, +${i.time_delta_days}d` : ''})`).join('\n')
  : '(sin imprevistos esta semana)';

const systemPrompt = `Eres un asistente del estudio de arquitectura redactando un email semanal al cliente ${r.client_name} sobre su obra "${r.project_name}" en ${r.location_city || 'su domicilio'}. Tono: profesional, cercano, claro, sin jerga tecnica innecesaria. Idioma: castellano de Espana. Longitud objetivo del summary_text: 150-200 palabras. Devuelve SOLO JSON valido con la forma { summary_text: string, hitos_principales: string[], proxima_semana: string }. No inventes datos, fechas ni cifras que no aparezcan en el contexto. Si la semana ha sido tranquila, di la verdad de forma profesional (estamos avanzando en X, sin novedades urgentes). Saluda y despide cordialmente. Firma como "El equipo de tu estudio de arquitectura".`;

const userPrompt = `CONTEXTO DE LA SEMANA (${weekStartStr} a ${weekEndStr})\n\nFASE ACTUAL DEL PROYECTO: ${r.current_phase}\nMUNICIPIO: ${r.location_city || '(no especificado)'}\n\nACTIVIDAD DE AGENTES IA:\n${activitySummary}\n\nVISITAS DE OBRA (actas firmadas):\n${visitsSummary}\n\nIMPREVISTOS DETECTADOS:\n${incidentsSummary}\n\nGenera el email semanal para el cliente.`;

return [{ json: {
  ...sess,
  project_id: r.project_id,
  project_name: r.project_name,
  client_name: r.client_name,
  client_email: r.client_email,
  location_city: r.location_city,
  current_phase: r.current_phase,
  week_start: weekStartStr,
  week_end: weekEndStr,
  has_activity: activity.length > 0 || visits.length > 0 || incidents.length > 0,
  activity_count: activity.length,
  visits_count: visits.length,
  incidents_count: incidents.length,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.4,
    max_tokens: 700,
    response_format: { type: 'json_object' }
  }
}}];

