const llm = $input.first()?.json;
const ctx = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message } }];
}
const summary = String(parsed.summary_text || '').trim();
if (!summary || summary.length < 50) {
  return [{ json: { _error: 'LLM_EMPTY_SUMMARY', _status: 502, _details: 'summary_text vacio o demasiado corto' } }];
}
const hitos = Array.isArray(parsed.hitos_principales) ? parsed.hitos_principales.slice(0, 6) : [];
const proxima = String(parsed.proxima_semana || '').trim();
const usage = llm?.usage || {};
return [{ json: {
  ...ctx,
  summary_text: summary,
  hitos_principales: hitos,
  proxima_semana: proxima,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

